def transforms(sh):
    out=[]
    pts=set(sh)
    for k in range(4):
      for refl in [False,True]:
       q=[]
       for r,c in pts:
        if refl:c=-c
        for _ in range(k):r,c=c,-r
        q.append((r,c))
       mr=min(r for r,c in q); mc=min(c for r,c in q)
       q=tuple(sorted((r-mr,c-mc) for r,c in q))
       if q not in out:out.append(q)
    return out
